import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable, throwError } from 'rxjs';
import { catchError, map } from 'rxjs/operators';
import { getConfig } from '../app-config';
import { FormConfig } from './form-config';

@Injectable({
    providedIn: 'root'
})
export class ProxyService {

    constructor(private readonly httpClient: HttpClient) {
    }

    uniqueSubmissionCheck(formConfig: FormConfig): Observable<any> {
        return this.httpClient.post(`${getConfig().proxyUrl}/secure/check/unique/submission`, formConfig, { withCredentials: true })
            .pipe(
                map(this.extractData),
                catchError(this.handleError)
            );
    }

    addressData(addressSearchValue: any): Observable<any> {
        return this.httpClient.get(`${getConfig().proxyUrl}/address/search?search=` + addressSearchValue, { withCredentials: true })
    }

    // eslint-disable-next-line 
    extractData(res: any) {
        const body = res;
        return body || {};
    }

    // eslint-disable-next-line
    handleError(error: HttpErrorResponse) {
        let errorMessage = 'Unknown error!';
        if (error.error instanceof ErrorEvent) {
            // Client-side errors
            errorMessage = `Error: ${error.error.message}`;
        } else {
            // Server-side errors
            errorMessage = `Error Code: ${error.status}\nMessage: ${error.message}`;
        }
        return throwError(errorMessage);
    }
}
