import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { AllowedGuard } from './allowed.guard';
import { getConfig } from './app-config';
import { AuthGuard } from './auth/auth.guard';
import { EmployeeAuthGuard } from './auth/employee.auth.guard';
import { LoginComponent } from './auth/login/login.component';
import { LoginfailedComponent } from './auth/loginfailed/loginfailed.component';
import { LogoutComponent } from './auth/logout/logout.component';
import { EmployeeComponent } from './employee/employee.component';
import { ErrorComponent } from './error/error.component';
import { PaymentfailedComponent } from './error/paymentfailed/paymentfailed.component';
import { UniquesubmissionComponent } from './error/uniquesubmission/uniquesubmission.component';
import { FormComponent } from './form/form.component';
import { HomeComponent } from './home/home.component';
import { NotfoundComponent } from './notfound/notfound.component';
import { PaymentComponent } from './payment/payment.component';
import { PaymentSuccessComponent } from './payment/paymentsuccess.component';
import { StartPaymentComponent } from './payment/start-payment/start-payment.component';
import { PaymentsuccessfulComponent } from './paymentsuccessful/paymentsuccessful.component';
import { StageComponent } from './stage/stage.component';
import { ThanksComponent } from './thanks/thanks.component';
import { UnauthorizedComponent } from './unauthorized/unauthorized.component';
import {UnauthorizedLoginMethodComponent} from './unauthorized-login-method/unauthorized-login-method.component';

const routes: Routes = [
  {
    path: '',
    redirectTo: '/home',
    pathMatch: 'full'
  },
  {
    path: 'home',
    component: HomeComponent,
    canActivate : [AllowedGuard],
  },
  {
    path: 'stage',
    component: StageComponent,
    canActivate : [AllowedGuard],
  },
  {
    path: 'loginfailed',
    component: LoginfailedComponent
  },
  {
    path: 'unique-submission-error',
    component: UniquesubmissionComponent
  },
  {
    path: 'payment/successful',
    component: PaymentsuccessfulComponent
  },
  {
    path: 'payment/start',
    component: StartPaymentComponent
  },
  {
    path: 'notfound',
    component: NotfoundComponent
  },
  {
    path: 'payment',
    component: PaymentComponent
  },
  {
    path: 'direct-payment/success',
    component: PaymentSuccessComponent
  },
  {
    path: 'payment/cancel',
    component: PaymentfailedComponent
  },
  {
    path: 'payment/decline',
    component: PaymentfailedComponent
  },
  {
    path: 'payment/exception',
    component: PaymentfailedComponent
  },
  {
    path: 'thanks',
    component: ThanksComponent
  },
  {
    path: '403',
    component: UnauthorizedComponent
  },
  {
    path: 'unauthorized-login-method',
    component: UnauthorizedLoginMethodComponent
  },
  {
    path: 'error',
    component: ErrorComponent
  },
  {
    path: 'form',
    canActivate : [AuthGuard],
    component: FormComponent
  },
  {
    path: 'form/:stageName/:formName',
    redirectTo: 'form/:stageName/:formName/1',
    pathMatch: 'full'
  },
  {
    path: 'form/:stageName/:formName/:pageNumber',
    canActivate : [AuthGuard],
    component: FormComponent
  },
  {
    path: 'secure',
    canActivate : [AuthGuard],
    component: FormComponent
  },
  {
    path: 'secure/:stageName/:formName/:pageNumber',
    canActivate : [AuthGuard],
    component: FormComponent
  },
  {
    path: 'secure/:formName/:pageNumber',
    canActivate : [AuthGuard],
    component: FormComponent
  },
  {
    path: 'secure/employee',
    canActivate : [EmployeeAuthGuard],
    component: EmployeeComponent
  },
  {
    path: 'login',
    component: LoginComponent
  },
  {
    path: 'logout',
    component: LogoutComponent
  },
  { path: '**', pathMatch: 'full',
    component: NotfoundComponent },
];

@NgModule({
  imports: [RouterModule.forRoot(routes, {useHash: getConfig().routerUserHash})],
  exports: [RouterModule]
})
export class AppRoutingModule { }
