import {Component, HostListener} from '@angular/core';
import {Components, Templates, Formio} from 'formiojs';
import Switch from '@yourrequest/nijmegen-custom-components/lib/components/Switch/Switch';
import SwitchTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/switch';
import checkboxnijmegen from '@yourrequest/nijmegen-custom-components/lib/components/checkboxnijmegen/checkboxnijmegen';
import DatetimeNijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Datetime_Nijmegen/DateTime_nijmegen';
import TextField_nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Textfield_nijmegen/TextField_nijmegen';
import Email_nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Email_Nijmegen/Email_Nijmegen';
import InputTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/input';
import FieldTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/field';
import RadioTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/radionijmegen';
import FileTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/filenijmegen';
import checkboxnijmegentemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/checkboxnijmegen';
import TextArea_Nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Textarea_Nijmegen/TextArea_Nijmegen';
import SelectBoxes_Nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Selectboxes_Nijmegen/SelectBoxes_Nijmegen';
import File_Nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/File_Nijmegen/File_Nijmegen';
import Radio_Nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Radio_Nijmegen/Radio_Nijmegen';
import Address_nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/addressnijmegen/Address_nijmegen';
import AddressTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/addressnijmegen';
import {AuthService} from './auth/auth.service';
import Summary from '@yourrequest/nijmegen-custom-components/lib/components/Summary/SummaryComponent';
import SummaryTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/summary';
import select_nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/selectnijmegen/Select_nijmegen';
import time_nijmegen from '@yourrequest/nijmegen-custom-components/lib/components/Time_Nijmegen/Time';
import SelectTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/selectnijmegen';
import IconTemplate from '@yourrequest/nijmegen-custom-components/lib/templates/bootstrap/iconnijmegen';

import ProtectedEval from '@formio/protected-eval';

@Component({
    selector: 'app-root',
    templateUrl: './app.component.html',
    styleUrls: ['./app.component.scss']
})

export class AppComponent {

    title = 'form-renderer';
    sessionModal = false;
    sessionInactivityTimer = 0; // in minutes, when to show the session popup, due to inactivity
    sessionExpiredTimer = 0; // in minutes, when to show the session popup, due to inactivity
    sessionStartDate: Date = new Date();
    sessionRefreshDate: Date = new Date();
    sessionRefreshTimer = 30 * 1000; // every 30 seconds, when to refresh the session

    constructor(
        private authService: AuthService
    ) {
        this.initializeApp();
    }

    @HostListener('document:keypress', ['$event'])
    handleKeyboardEvent(): void {
        this.resetSessionTimer();
    }

    @HostListener('click', ['$event.target'])
    clickButton(): void {
        this.resetSessionTimer();
    }

    async initializeApp() {
        Formio.use(ProtectedEval);

        Templates.current['checkboxnijmegen'] = checkboxnijmegentemplate;
        Components.addComponent('checkboxnijmegen', checkboxnijmegen);

        Templates.current['switch'] = SwitchTemplate;
        Components.addComponent('switch', Switch);

        Components.addComponent('datetime_nijmegen', DatetimeNijmegen);
        Components.addComponent('textfield_nijmegen', TextField_nijmegen);
        Components.addComponent('selectboxes_nijmegen', SelectBoxes_Nijmegen);
        Components.addComponent('file_nijmegen', File_Nijmegen);
        Components.addComponent('radio_nijmegen', Radio_Nijmegen);
        Components.addComponent('email_nijmegen', Email_nijmegen);
        Components.addComponent('textarea_nijmegen', TextArea_Nijmegen);
        Components.addComponent('adres_nijmegen', Address_nijmegen);
        Components.addComponent('summary', Summary);
        Components.addComponent('select_nijmegen', select_nijmegen);
        Components.addComponent('time_nijmegen', time_nijmegen);
        Templates.current['input'] = InputTemplate;
        Templates.current['field'] = FieldTemplate;
        Templates.current['radionijmegen'] = RadioTemplate;
        Templates.current['filenijmegen'] = FileTemplate;
        Templates.current['addressnijmegen'] = AddressTemplate;
        Templates.current['summary'] = SummaryTemplate;
        Templates.current['selectnijmegen'] = SelectTemplate;
        Templates.current['iconnijmegen'] = IconTemplate;

        // init session timer, but only if the user is logged in
        if (this.authService.isAuthenticated()){
            this.resetSessionTimer();
            this.sessionTimerChecker();
            setInterval(() => {this.sessionTimerChecker(); }, 10000);
        }else{
            this.authService.removeLocalUserdata(true);
        }
    }

    resetSessionTimer(): void {
        this.sessionInactivityTimer = 14 * 60 * 1000;
        this.sessionExpiredTimer = 15 * 60 * 1000;
        this.sessionStartDate = new Date();
    }

    showSessionModal(): void {
        this.sessionModal = true;
    }

    hideSessionModal(): void {
        this.sessionModal = false;
    }

    refreshSession(): void {
        this.sessionModal = false;
        this.resetSessionTimer();
        this.authService.refreshToken();
        this.sessionRefreshDate = new Date();
    }

    sessionTimerChecker(): void{

        const now = new Date();

        // Trigger refresh token
        const sessionTriggerRefreshDate = new Date(this.sessionRefreshDate.getTime() + this.sessionRefreshTimer);
        if (now >= sessionTriggerRefreshDate) {
            this.authService.refreshToken();
            this.sessionRefreshDate = new Date();
        }

        // Trigger inactivity modal
        const sessionInactivityTimerDate = new Date(this.sessionStartDate.getTime() + this.sessionInactivityTimer);
        if (now >= sessionInactivityTimerDate){
            this.showSessionModal();
        }

        // Trigger logout
        const sessionExpiredTimerDate = new Date(this.sessionStartDate.getTime() + this.sessionExpiredTimer);
        if (now >= sessionExpiredTimerDate){
            this.hideSessionModal();
            this.authService.logout();
        }
    }
}
