import {ChangeDetectorRef, Component, EventEmitter, Input, OnInit} from '@angular/core';
import {ActivatedRoute, Params} from '@angular/router';

@Component({
  selector: 'app-formstepper',
  templateUrl: './formstepper.component.html',
  styleUrls: ['./formstepper.component.scss']
})
export class FormstepperComponent implements OnInit {

  formName = '';
  stageName = '';
  currentPage: number = 0;
  totalPages: number | undefined = 0;

  pages: any[] = []
  @Input() pagesEmitter: EventEmitter<any[]> = new EventEmitter<any[]>();

  constructor(public activeRoute: ActivatedRoute,
              private chRef: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.activeRoute.params
        .subscribe((params: Params) => {
          if (params.formName) {
            if (params.stageName) {
              this.stageName = params.stageName;
            }
            this.formName = params.formName;
          }
          if (params.pageNumber) {
            this.currentPage = params.pageNumber
          }

            this.pagesEmitter.subscribe((pagesArray: any[]) => {
                this.totalPages = pagesArray.length;
                this.pages = pagesArray
                this.chRef.detectChanges();
            });
        });
  }

  getClass(index: number): string {
      if(index < this.currentPage) {
          return 'previous';
      } else if(index > this.currentPage) {
          return 'next';
      }
      return 'current';
  }

    isNotlastStep(index: number): boolean {
      if(this.totalPages) {
          return index < this.totalPages;
      }
      return false;
    }

    isComplete(index: number): boolean {
        return index < this.currentPage;
    }

    stepLink(index: number): string {
      return '/#/form/' + this.stageName + '/' + this.formName + '/' + index
    }
}
